   0 /**
   1  * Embedding Service using Ollama
   2  * 
   3  * This module provides text embedding functionality using Ollama's embedding models.
   4  * Ollama supports models like nomic-embed-text for generating embeddings.
   5  */
   6 
   7 
   8 
   9 export interface EmbeddingResult {
  10   embedding: number[];
  11   model: string;
  12 }
  13 
  14 /**
  15  * Generate embeddings using Ollama
  16  */
  17 export async function generateEmbedding(text: string): Promise<number[]> {
  18   try {
  19     const response = await fetch(`http://185.190.140.93:11434/api/embeddings`, {
  20       method: 'POST',
  21       headers: {
  22         'Content-Type': 'application/json',
  23       },
  24       body: JSON.stringify({
  25         model: 'nomic-embed-text', // Ollama embedding model
  26         prompt: text,
  27       }),
  28     });
  29 
  30     if (!response.ok) {
  31       throw new Error(`Ollama API error: ${response.status} ${response.statusText}`);
  32     }
  33 
  34     const data = await response.json();
  35     return data.embedding;
  36   } catch (error) {
  37     console.error('Error generating embedding:', error);
  38     throw new Error(`Failed to generate embedding: ${error instanceof Error ? error.message : 'Unknown error'}`);
  39   }
  40 }
  41 
  42 /**
  43  * Generate embeddings for multiple texts in batch
  44  */
  45 export async function generateEmbeddings(texts: string[]): Promise<number[][]> {
  46   try {
  47     // Process in parallel for better performance
  48     const embeddings = await Promise.all(
  49       texts.map(text => generateEmbedding(text))
  50     );
  51     return embeddings;
  52   } catch (error) {
  53     console.error('Error generating batch embeddings:', error);
  54     throw error;
  55   }
  56 }
  57 
  58 /**
  59  * Split text into chunks for embedding
  60  * This is important because embedding models have token limits
  61  */
  62 export function chunkText(
  63   text: string,
  64   options: {
  65     chunkSize?: number;
  66     overlap?: number;
  67     preserveParagraphs?: boolean;
  68   } = {}
  69 ): string[] {
  70   const {
  71     chunkSize = 500, // characters
  72     overlap = 50,
  73     preserveParagraphs = true,
  74   } = options;
  75 
  76   if (text.length <= chunkSize) {
  77     return [text];
  78   }
  79 
  80   const chunks: string[] = [];
  81 
  82   if (preserveParagraphs) {
  83     // Split by paragraphs first
  84     const paragraphs = text.split(/\n\n+/);
  85     let currentChunk = '';
  86 
  87     for (const paragraph of paragraphs) {
  88       if ((currentChunk + paragraph).length <= chunkSize) {
  89         currentChunk += (currentChunk ? '\n\n' : '') + paragraph;
  90       } else {
  91         if (currentChunk) {
  92           chunks.push(currentChunk);
  93         }
  94         
  95         // If single paragraph is larger than chunk size, split it
  96         if (paragraph.length > chunkSize) {
  97           const subChunks = splitLongText(paragraph, chunkSize, overlap);
  98           chunks.push(...subChunks);
  99           currentChunk = '';
 100         } else {
 101           currentChunk = paragraph;
 102         }
 103       }
 104     }
 105 
 106     if (currentChunk) {
 107       chunks.push(currentChunk);
 108     }
 109   } else {
 110     // Simple character-based chunking with overlap
 111     return splitLongText(text, chunkSize, overlap);
 112   }
 113 
 114   return chunks;
 115 }
 116 
 117 /**
 118  * Split long text into chunks with overlap
 119  */
 120 function splitLongText(text: string, chunkSize: number, overlap: number): string[] {
 121   const chunks: string[] = [];
 122   let start = 0;
 123 
 124   while (start < text.length) {
 125     const end = Math.min(start + chunkSize, text.length);
 126     chunks.push(text.slice(start, end));
 127     start = end - overlap;
 128     
 129     if (start >= text.length - overlap) break;
 130   }
 131 
 132   return chunks;
 133 }
 134 
 135 /**
 136  * Calculate the number of tokens (approximate)
 137  * This is a rough estimate: ~4 characters per token for English
 138  */
 139 export function estimateTokens(text: string): number {
 140   return Math.ceil(text.length / 4);
 141 }
