   0 /**
   1  * Vector Store Implementation for RAG
   2  * 
   3  * This module provides a simple in-memory vector store with persistence to Firestore.
   4  * For production, consider using dedicated vector databases like Pinecone or Qdrant.
   5  */
   6 
   7 import { db } from '@/lib/firebase/server-init';
   8 import { collection, doc, setDoc, getDocs, query, where, Timestamp } from 'firebase/firestore';
   9 
  10 export interface DocumentChunk {
  11   id: string;
  12   content: string;
  13   embedding?: number[];
  14   metadata: {
  15     projectId?: string;
  16     userId?: string;
  17     sourceFile?: string;
  18     chunkIndex: number;
  19     timestamp: number;
  20     type: 'report' | 'reference' | 'context' | 'user_upload';
  21   };
  22 }
  23 
  24 export interface SearchResult {
  25   chunk: DocumentChunk;
  26   score: number;
  27 }
  28 
  29 /**
  30  * Calculate cosine similarity between two vectors
  31  */
  32 function cosineSimilarity(a: number[], b: number[]): number {
  33   if (a.length !== b.length) {
  34     throw new Error('Vectors must have the same length');
  35   }
  36 
  37   let dotProduct = 0;
  38   let normA = 0;
  39   let normB = 0;
  40 
  41   for (let i = 0; i < a.length; i++) {
  42     dotProduct += a[i] * b[i];
  43     normA += a[i] * a[i];
  44     normB += b[i] * b[i];
  45   }
  46 
  47   const denominator = Math.sqrt(normA) * Math.sqrt(normB);
  48   return denominator === 0 ? 0 : dotProduct / denominator;
  49 }
  50 
  51 /**
  52  * Vector Store Class
  53  */
  54 export class VectorStore {
  55   private chunks: Map<string, DocumentChunk> = new Map();
  56   private collectionName = 'vector_embeddings';
  57 
  58   /**
  59    * Add a document chunk to the vector store
  60    */
  61   async addChunk(chunk: DocumentChunk): Promise<void> {
  62     this.chunks.set(chunk.id, chunk);
  63 
  64     // Persist to Firestore
  65     try {
  66       const docRef = doc(db, this.collectionName, chunk.id);
  67       await setDoc(docRef, {
  68         content: chunk.content,
  69         embedding: chunk.embedding || [],
  70         metadata: chunk.metadata,
  71         createdAt: Timestamp.now(),
  72       });
  73     } catch (error) {
  74       console.error('Error persisting chunk to Firestore:', error);
  75       // Don't throw - allow in-memory storage to continue
  76     }
  77   }
  78 
  79   /**
  80    * Add multiple chunks at once
  81    */
  82   async addChunks(chunks: DocumentChunk[]): Promise<void> {
  83     await Promise.all(chunks.map(chunk => this.addChunk(chunk)));
  84   }
  85 
  86   /**
  87    * Search for similar chunks using cosine similarity
  88    */
  89   async search(
  90     queryEmbedding: number[],
  91     options: {
  92       topK?: number;
  93       minScore?: number;
  94       filter?: Partial<DocumentChunk['metadata']>;
  95     } = {}
  96   ): Promise<SearchResult[]> {
  97     const { topK = 5, minScore = 0.5, filter } = options;
  98 
  99     // Filter chunks based on metadata if provided
 100     let relevantChunks = Array.from(this.chunks.values());
 101 
 102     if (filter) {
 103       relevantChunks = relevantChunks.filter(chunk => {
 104         if (filter.projectId && chunk.metadata.projectId !== filter.projectId) return false;
 105         if (filter.userId && chunk.metadata.userId !== filter.userId) return false;
 106         if (filter.type && chunk.metadata.type !== filter.type) return false;
 107         return true;
 108       });
 109     }
 110 
 111     // Calculate similarities
 112     const results: SearchResult[] = relevantChunks
 113       .filter(chunk => chunk.embedding && chunk.embedding.length > 0)
 114       .map(chunk => ({
 115         chunk,
 116         score: cosineSimilarity(queryEmbedding, chunk.embedding!),
 117       }))
 118       .filter(result => result.score >= minScore)
 119       .sort((a, b) => b.score - a.score)
 120       .slice(0, topK);
 121 
 122     return results;
 123   }
 124 
 125   /**
 126    * Load chunks from Firestore for a specific project
 127    */
 128   async loadProjectChunks(projectId: string): Promise<void> {
 129     try {
 130       const q = query(
 131         collection(db, this.collectionName),
 132         where('metadata.projectId', '==', projectId)
 133       );
 134 
 135       const snapshot = await getDocs(q);
 136       snapshot.forEach(doc => {
 137         const data = doc.data();
 138         const chunk: DocumentChunk = {
 139           id: doc.id,
 140           content: data.content,
 141           embedding: data.embedding,
 142           metadata: data.metadata,
 143         };
 144         this.chunks.set(chunk.id, chunk);
 145       });
 146     } catch (error) {
 147       console.error('Error loading chunks from Firestore:', error);
 148     }
 149   }
 150 
 151   /**
 152    * Clear all chunks (useful for testing)
 153    */
 154   clear(): void {
 155     this.chunks.clear();
 156   }
 157 
 158   /**
 159    * Get total number of chunks
 160    */
 161   size(): number {
 162     return this.chunks.size;
 163   }
 164 }
 165 
 166 // Singleton instance
 167 let vectorStoreInstance: VectorStore | null = null;
 168 
 169 export function getVectorStore(): VectorStore {
 170   if (!vectorStoreInstance) {
 171     vectorStoreInstance = new VectorStore();
 172   }
 173   return vectorStoreInstance;
 174 }
