   0 /**
   1  * RAG Retrieval Service
   2  * 
   3  * This module provides the main RAG functionality: retrieving relevant context
   4  * from the vector store based on a query.
   5  */
   6 
   7 import { generateEmbedding } from './embeddings';
   8 import { getVectorStore, type SearchResult } from './vector-store';
   9 
  10 export interface RetrievalOptions {
  11   topK?: number;
  12   minScore?: number;
  13   projectId?: string;
  14   userId?: string;
  15   includeTypes?: Array<'report' | 'reference' | 'context' | 'user_upload'>;
  16 }
  17 
  18 export interface RetrievalResult {
  19   context: string;
  20   sources: Array<{
  21     content: string;
  22     score: number;
  23     sourceFile?: string;
  24     type: string;
  25   }>;
  26 }
  27 
  28 /**
  29  * Retrieve relevant context for a query using RAG
  30  */
  31 export async function retrieveContext(
  32   query: string,
  33   options: RetrievalOptions = {}
  34 ): Promise<RetrievalResult> {
  35   const {
  36     topK = 5,
  37     minScore = 0.5,
  38     projectId,
  39     userId,
  40     includeTypes,
  41   } = options;
  42 
  43   try {
  44     // 1. Generate embedding for the query
  45     const queryEmbedding = await generateEmbedding(query);
  46 
  47     // 2. Search vector store for similar chunks
  48     const vectorStore = getVectorStore();
  49     
  50     // Load project chunks if projectId is provided
  51     if (projectId) {
  52       await vectorStore.loadProjectChunks(projectId);
  53     }
  54 
  55     const searchResults = await vectorStore.search(queryEmbedding, {
  56       topK,
  57       minScore,
  58       filter: {
  59         projectId,
  60         userId,
  61         type: includeTypes?.[0], // Simple filter for now
  62       },
  63     });
  64 
  65     // 3. Format results
  66     const sources = searchResults.map(result => ({
  67       content: result.chunk.content,
  68       score: result.score,
  69       sourceFile: result.chunk.metadata.sourceFile,
  70       type: result.chunk.metadata.type,
  71     }));
  72 
  73     // 4. Combine context from top results
  74     const context = searchResults
  75       .map((result, idx) => {
  76         const source = result.chunk.metadata.sourceFile || 'Unknown';
  77         return `[Context ${idx + 1}] (Relevance: ${(result.score * 100).toFixed(1)}%, Source: ${source})\n${result.chunk.content}`;
  78       })
  79       .join('\n\n---\n\n');
  80 
  81     return {
  82       context,
  83       sources,
  84     };
  85   } catch (error) {
  86     console.error('Error retrieving context:', error);
  87     
  88     // Return empty context on error instead of failing
  89     return {
  90       context: '',
  91       sources: [],
  92     };
  93   }
  94 }
  95 
  96 /**
  97  * Retrieve context for multiple queries (batch processing)
  98  */
  99 export async function retrieveContextBatch(
 100   queries: string[],
 101   options: RetrievalOptions = {}
 102 ): Promise<RetrievalResult[]> {
 103   return Promise.all(
 104     queries.map(query => retrieveContext(query, options))
 105   );
 106 }
 107 
 108 /**
 109  * Enhanced retrieval with query expansion
 110  * Generates multiple variations of the query to improve recall
 111  */
 112 export async function retrieveContextEnhanced(
 113   query: string,
 114   options: RetrievalOptions = {}
 115 ): Promise<RetrievalResult> {
 116   // Generate query variations
 117   const queries = [
 118     query,
 119     // Add simple variations
 120     `What is ${query}?`,
 121     `Explain ${query}`,
 122   ];
 123 
 124   // Retrieve for all variations
 125   const results = await retrieveContextBatch(queries, {
 126     ...options,
 127     topK: Math.ceil((options.topK || 5) / queries.length),
 128   });
 129 
 130   // Merge and deduplicate results
 131   const allSources = results.flatMap(r => r.sources);
 132   const uniqueSources = Array.from(
 133     new Map(allSources.map(s => [s.content, s])).values()
 134   )
 135     .sort((a, b) => b.score - a.score)
 136     .slice(0, options.topK || 5);
 137 
 138   const context = uniqueSources
 139     .map((source, idx) => {
 140       return `[Context ${idx + 1}] (Relevance: ${(source.score * 100).toFixed(1)}%, Source: ${source.sourceFile || 'Unknown'})\n${source.content}`;
 141     })
 142     .join('\n\n---\n\n');
 143 
 144   return {
 145     context,
 146     sources: uniqueSources,
 147   };
 148 }
 149 
