   6 
   7 import { chunkText, generateEmbeddings } from './embeddings';
   8 import { getVectorStore, type DocumentChunk } from './vector-store';
   9 import { v4 as uuidv4 } from 'uuid';
  10 
  11 export interface IndexingOptions {
  12   projectId?: string;
