  16   overlap?: number;
  17   type?: 'report' | 'reference' | 'context' | 'user_upload';
  18 }
  19 
  20 export interface IndexingResult {
  21   success: boolean;
  22   chunksCreated: number;
  23   errors?: string[];
  24 }
