  26 /**
  27  * Index a document into the vector store
  28  */
  29 export async function indexDocument(
  30   content: string,
  31   options: IndexingOptions = {}
  32 ): Promise<IndexingResult> {
  33   const {
  34     projectId,
  35     userId,
  36     sourceFile,
  37     chunkSize = 500,
  38     overlap = 50,
  39     type = 'context',
  40   } = options;
  41 
  42   const errors: string[] = [];
  43 
  44   try {
  45     // 1. Split document into chunks
  46     const textChunks = chunkText(content, {
  47       chunkSize,
  48       overlap,
  49       preserveParagraphs: true,
  50     });
  51 
  52     console.log(`Split document into ${textChunks.length} chunks`);
  53 
  54     // 2. Generate embeddings for all chunks
  55     let embeddings: number[][];
  56     try {
  57       embeddings = await generateEmbeddings(textChunks);
  58     } catch (error) {
  59       errors.push(`Failed to generate embeddings: ${error instanceof Error ? error.message : 'Unknown error'}`);
  60       return {
  61         success: false,
  62         chunksCreated: 0,
  63         errors,
  64       };
  65     }
  66 
  67     // 3. Create document chunks with embeddings
  68     const documentChunks: DocumentChunk[] = textChunks.map((chunk, idx) => ({
  69       id: uuidv4(),
  70       content: chunk,
  71       embedding: embeddings[idx],
  72       metadata: {
  73         projectId,
  74         userId,
  75         sourceFile,
  76         chunkIndex: idx,
  77         timestamp: Date.now(),
  78         type,
  79       },
  80     }));
  81 
  82     // 4. Add chunks to vector store
  83     const vectorStore = getVectorStore();
  84     await vectorStore.addChunks(documentChunks);
  85 
  86     console.log(`Successfully indexed ${documentChunks.length} chunks`);
  87 
  88     return {
  89       success: true,
  90       chunksCreated: documentChunks.length,
  91     };
  92   } catch (error) {
  93     console.error('Error indexing document:', error);
  94     errors.push(error instanceof Error ? error.message : 'Unknown error');
  95     
  96     return {
  97       success: false,
  98       chunksCreated: 0,
  99       errors,
 100     };
 101   }
 102 }
 103 
 104 /**
 105  * Index multiple documents at once
 106  */
 107 export async function indexDocuments(
 108   documents: Array<{ content: string; options: IndexingOptions }>,
 109 ): Promise<IndexingResult[]> {
 110   return Promise.all(
 111     documents.map(doc => indexDocument(doc.content, doc.options))
 112   );
 113 }
 114 
 115 /**
 116  * Index project context (sections, chapters, etc.)
 117  * This is called when a report is generated to make it available for RAG
 118  */
 119 export async function indexProjectContext(
 120   projectId: string,
 121   userId: string,
 122   context: {
 123     sections?: Array<{ title: string; content: string }>;
 124     chapters?: Array<{ title: string; content: string }>;
 125     otherDocuments?: Array<{ title: string; content: string }>;
 126   }
 127 ): Promise<IndexingResult> {
 128   const documents: Array<{ content: string; options: IndexingOptions }> = [];
 129 
 130   // Add sections
 131   if (context.sections) {
 132     context.sections.forEach(section => {
 133       documents.push({
 134         content: `# ${section.title}\n\n${section.content}`,
 135         options: {
 136           projectId,
 137           userId,
 138           sourceFile: `Section: ${section.title}`,
 139           type: 'report',
 140         },
 141       });
 142     });
 143   }
 144 
 145   // Add chapters
 146   if (context.chapters) {
 147     context.chapters.forEach(chapter => {
 148       documents.push({
 149         content: `# ${chapter.title}\n\n${chapter.content}`,
 150         options: {
 151           projectId,
 152           userId,
 153           sourceFile: `Chapter: ${chapter.title}`,
 154           type: 'report',
 155         },
 156       });
 157     });
 158   }
 159 
 160   // Add other documents
 161   if (context.otherDocuments) {
 162     context.otherDocuments.forEach(doc => {
 163       documents.push({
 164         content: `# ${doc.title}\n\n${doc.content}`,
 165         options: {
 166           projectId,
 167           userId,
 168           sourceFile: doc.title,
 169           type: 'context',
 170         },
 171       });
 172     });
 173   }
 174 
 175   const results = await indexDocuments(documents);
 176 
 177   // Aggregate results
 178   const totalChunks = results.reduce((sum, r) => sum + r.chunksCreated, 0);
 179   const allErrors = results.flatMap(r => r.errors || []);
 180 
 181   return {
 182     success: results.every(r => r.success),
 183     chunksCreated: totalChunks,
 184     errors: allErrors.length > 0 ? allErrors : undefined,
 185   };
 186 }
