   0 /**
   1  * API Route: Index Document for RAG
   2  * 
   3  * POST /api/rag/index-document
   4  * 
   5  * Allows users to upload and index documents for RAG retrieval.
   6  */
   7 
   8 import { NextRequest, NextResponse } from 'next/server';
   9 import { z } from 'zod';
  10 import RAGService from '@/services/rag-service';
  11 
  12 const IndexDocumentSchema = z.object({
  13   content: z.string().min(1, 'Content is required'),
  14   fileName: z.string().min(1, 'File name is required'),
  15   userId: z.string().min(1, 'User ID is required'),
  16   projectId: z.string().optional(),
  17   type: z.enum(['user_upload', 'reference']).default('user_upload'),
  18 });
  19 
  20 export async function POST(request: NextRequest) {
  21   try {
  22     // Parse request body
  23     const body = await request.json();
  24     
  25     // Validate input
  26     const validation = IndexDocumentSchema.safeParse(body);
  27     if (!validation.success) {
  28       return NextResponse.json(
  29         { error: 'Invalid input', details: validation.error.errors },
  30         { status: 400 }
  31       );
  32     }
  33 
  34     const { content, fileName, userId, projectId, type } = validation.data;
  35 
  36     // Index the document
  37     let result;
  38     if (type === 'reference') {
  39       result = await RAGService.indexReferenceMaterial(
  40         content,
  41         fileName,
  42         userId,
  43         projectId
  44       );
  45     } else {
  46       result = await RAGService.indexUserDocument(
  47         content,
  48         fileName,
  49         userId,
  50         projectId
  51       );
  52     }
  53 
  54     if (!result.success) {
  55       return NextResponse.json(
  56         { error: 'Failed to index document', details: result.errors },
  57         { status: 500 }
  58       );
  59     }
  60 
  61     return NextResponse.json({
  62       success: true,
  63       message: 'Document indexed successfully',
  64       chunksCreated: result.chunksCreated,
  65     });
  66 
  67   } catch (error) {
  68     console.error('Error in index-document API:', error);
  69     return NextResponse.json(
  70       { error: 'Internal server error', message: error instanceof Error ? error.message : 'Unknown error' },
  71       { status: 500 }
  72     );
  73   }
  74 }
