   0 /**
   1  * RAG Service
   2  * 
   3  * High-level service for managing RAG operations in the application.
   4  * This service provides convenient methods for document indexing and retrieval.
   5  */
   6 
   7 import { indexDocument, indexProjectContext, type IndexingOptions, type IndexingResult } from '@/lib/rag/indexer';
   8 import { retrieveContext, type RetrievalOptions, type RetrievalResult } from '@/lib/rag/retrieval';
   9 import { getVectorStore } from '@/lib/rag/vector-store';
  10 
  11 export class RAGService {
  12   /**
  13    * Index a user-uploaded document
  14    */
  15   static async indexUserDocument(
  16     content: string,
  17     fileName: string,
  18     userId: string,
  19     projectId?: string
  20   ): Promise<IndexingResult> {
  21     return indexDocument(content, {
  22       userId,
  23       projectId,
  24       sourceFile: fileName,
  25       type: 'user_upload',
  26       chunkSize: 500,
  27       overlap: 50,
  28     });
  29   }
  30 
  31   /**
  32    * Index reference materials (PDFs, articles, etc.)
  33    */
  34   static async indexReferenceMaterial(
  35     content: string,
  36     title: string,
  37     userId: string,
  38     projectId?: string
  39   ): Promise<IndexingResult> {
  40     return indexDocument(content, {
  41       userId,
  42       projectId,
  43       sourceFile: title,
  44       type: 'reference',
  45       chunkSize: 600,
  46       overlap: 100,
  47     });
  48   }
  49 
  50   /**
  51    * Index generated report sections and chapters
  52    */
  53   static async indexGeneratedReport(
  54     projectId: string,
  55     userId: string,
  56     sections: Array<{ title: string; content: string }>,
  57     chapters?: Array<{ title: string; content: string }>
  58   ): Promise<IndexingResult> {
  59     return indexProjectContext(projectId, userId, {
  60       sections,
  61       chapters,
  62     });
  63   }
  64 
  65   /**
  66    * Retrieve relevant context for report generation
  67    */
  68   static async getRelevantContext(
  69     query: string,
  70     projectId: string,
  71     userId: string,
  72     options: Partial<RetrievalOptions> = {}
  73   ): Promise<RetrievalResult> {
  74     return retrieveContext(query, {
  75       projectId,
  76       userId,
  77       topK: 5,
  78       minScore: 0.5,
  79       ...options,
  80     });
  81   }
  82 
  83   /**
  84    * Load project vector data into memory
  85    */
  86   static async loadProjectData(projectId: string): Promise<void> {
  87     const vectorStore = getVectorStore();
  88     await vectorStore.loadProjectChunks(projectId);
  89   }
  90 
  91   /**
  92    * Get statistics about indexed documents
  93    */
  94   static getIndexStats(): { totalChunks: number } {
  95     const vectorStore = getVectorStore();
  96     return {
  97       totalChunks: vectorStore.size(),
  98     };
  99   }
 100 
 101   /**
 102    * Clear all indexed data (use with caution!)
 103    */
 104   static clearIndex(): void {
 105     const vectorStore = getVectorStore();
 106     vectorStore.clear();
 107   }
 108 }
 109 
 110 export default RAGService;
