   0 /**
   1  * Hook: useRAGIndexing
   2  * 
   3  * React hook for indexing documents into the RAG system
   4  */
   5 
   6 import { useState } from 'react';
   7 import { useAuthContext } from '@/context/AuthContext';
   8 
   9 interface IndexingState {
  10   isIndexing: boolean;
  11   error: string | null;
  12   success: boolean;
  13   chunksCreated: number;
  14 }
  15 
  16 export function useRAGIndexing() {
  17   const { user } = useAuthContext();
  18   const [state, setState] = useState<IndexingState>({
  19     isIndexing: false,
  20     error: null,
  21     success: false,
  22     chunksCreated: 0,
  23   });
  24 
  25   const indexDocument = async (
  26     content: string,
  27     fileName: string,
  28     projectId?: string,
  29     type: 'user_upload' | 'reference' = 'user_upload'
  30   ) => {
  31     if (!user) {
  32       setState(prev => ({ ...prev, error: 'User not authenticated' }));
  33       return false;
  34     }
  35 
  36     setState({
  37       isIndexing: true,
  38       error: null,
  39       success: false,
  40       chunksCreated: 0,
  41     });
  42 
  43     try {
  44       const response = await fetch('/api/rag/index-document', {
  45         method: 'POST',
  46         headers: {
  47           'Content-Type': 'application/json',
  48         },
  49         body: JSON.stringify({
  50           content,
  51           fileName,
  52           userId: user.uid,
  53           projectId,
  54           type,
  55         }),
  56       });
  57 
  58       const data = await response.json();
  59 
  60       if (!response.ok) {
  61         throw new Error(data.error || 'Failed to index document');
  62       }
  63 
  64       setState({
  65         isIndexing: false,
  66         error: null,
  67         success: true,
  68         chunksCreated: data.chunksCreated || 0,
  69       });
  70 
  71       return true;
  72     } catch (error) {
  73       const errorMessage = error instanceof Error ? error.message : 'Unknown error';
  74       setState({
  75         isIndexing: false,
  76         error: errorMessage,
  77         success: false,
  78         chunksCreated: 0,
  79       });
  80       return false;
  81     }
  82   };
  83 
  84   const indexMultipleDocuments = async (
  85     documents: Array<{
  86       content: string;
  87       fileName: string;
  88       type?: 'user_upload' | 'reference';
  89     }>,
  90     projectId?: string
  91   ) => {
  92     if (!user) {
  93       setState(prev => ({ ...prev, error: 'User not authenticated' }));
  94       return false;
  95     }
  96 
  97     setState({
  98       isIndexing: true,
  99       error: null,
 100       success: false,
 101       chunksCreated: 0,
 102     });
 103 
 104     try {
 105       let totalChunks = 0;
 106       const errors: string[] = [];
 107 
 108       for (const doc of documents) {
 109         const success = await indexDocument(
 110           doc.content,
 111           doc.fileName,
 112           projectId,
 113           doc.type || 'user_upload'
 114         );
 115 
 116         if (success) {
 117           totalChunks += state.chunksCreated;
 118         } else {
 119           errors.push(`Failed to index: ${doc.fileName}`);
 120         }
 121       }
 122 
 123       if (errors.length > 0) {
 124         setState({
 125           isIndexing: false,
 126           error: errors.join(', '),
 127           success: false,
 128           chunksCreated: totalChunks,
 129         });
 130         return false;
 131       }
 132 
 133       setState({
 134         isIndexing: false,
 135         error: null,
 136         success: true,
 137         chunksCreated: totalChunks,
 138       });
 139 
 140       return true;
 141     } catch (error) {
 142       const errorMessage = error instanceof Error ? error.message : 'Unknown error';
 143       setState({
 144         isIndexing: false,
 145         error: errorMessage,
 146         success: false,
 147         chunksCreated: 0,
 148       });
 149       return false;
 150     }
 151   };
 152 
 153   const reset = () => {
 154     setState({
 155       isIndexing: false,
 156       error: null,
 157       success: false,
 158       chunksCreated: 0,
 159     });
 160   };
 161 
 162   return {
 163     indexDocument,
 164     indexMultipleDocuments,
 165     reset,
 166     ...state,
 167   };
 168 }
