    minVectorScore: 0.4,
    minKeywordScore: 0.3,
  },

  // BM25 Parameters
  bm25: {
    k1: 1.5, // Term frequency saturation parameter
    b: 0.75, // Length normalization parameter
  },

  // Query Processing
  query: {
    maxQueryLength: 1000,
    enableSpellCorrection: true,
    enableQueryExpansion: true,
    maxExpansions: 3,
    minQueryLength: 2,
  },

  // Chunking Settings
  chunking: {
    defaultChunkSize: 500,
    largeChunkSize: 800,
    overlap: 50,
    largeOverlap: 100,
  },

  // Caching
  cache: {
    enableQueryCache: true,
    cacheTTL: 3600000, // 1 hour in milliseconds
    maxCacheSize: 1000,
  },

  // Analytics
  analytics: {
    enableTracking: true,
    trackClicks: true,
    trackQueries: true,
    sampleRate: 1.0, // Track 100% of queries
  },

  // Performance
  performance: {
    batchSize: 10,
    maxConcurrentQueries: 5,
    timeout: 30000, // 30 seconds
  },

  // Document Types
  documentTypes: [
    'report',
    'reference',
    'context',
    'user_upload',
    'academic_paper',
    'lecture',
    'presentation',
  ] as const,

  // Supported Languages
  languages: ['en', 'ar'] as const,
};

export type DocumentType = (typeof SearchConfig.documentTypes)[number];
export type SupportedLanguage = (typeof SearchConfig.languages)[number];

/**
 * Search Mode Enum
 */
export enum SearchMode {
  VECTOR = 'vector',
