{"file_path": "src/lib/search-engine/ranking.ts", "initial_content": "/**
 * Advanced Ranking Algorithms for Search Engine
 * 
 * Implements various ranking strategies including BM25, RRF, and custom scoring
 */

import { SearchConfig } from './search-config';

export interface RankedDocument {
  id: string;
  content: string;
  score: number;
  metadata?: Record<string, any>;
  highlights?: string[];
}

export interface DocumentWithTerms {
  id: string;
  content: string;
  terms: string[];
  metadata?: Record<string, any>;
}

/**
 * Calculate BM25 score for a document
 * BM25 is a ranking function used in information retrieval
 */
export function calculateBM25Score(
  queryTerms: string[],
  document: DocumentWithTerms,
  corpus: DocumentWithTerms[],
  options?: {
    k1?: number;
    b?: number;
  }
): number {
  const { k1 = SearchConfig.bm25.k1, b = SearchConfig.bm25.b } = options || {};

  // Calculate corpus statistics
  const corpusLength = corpus.length;
  const avgDocLength =
    corpus.reduce((sum, doc) => sum + doc.terms.length, 0) / corpusLength;
  const docLength = document.terms.length;

  let score = 0;

  for (const term of queryTerms) {
    // Calculate IDF (Inverse Document Frequency)
    const docsWithTerm = corpus.filter((doc) =>
      doc.terms.includes(term.toLowerCase())
    ).length;
    const idf = Math.log(
      (corpusLength - docsWithTerm + 0.5) / (docsWithTerm + 0.5) + 1
    );

    // Calculate term frequency in document
    const termFreq = document.terms.filter(
      (t) => t.toLowerCase() === term.toLowerCase()
    ).length;

    // BM25 formula
    const numerator = termFreq * (k1 + 1);
    const denominator =
      termFreq + k1 * (1 - b + b * (docLength / avgDocLength));
    const termScore = idf * (numerator / denominator);

    score += termScore;
  }

  return score;
}

/**
 * Reciprocal Rank Fusion (RRF)
 * Combines multiple ranked lists into a single ranking
 */
export function reciprocalRankFusion(
  rankedLists: RankedDocument[][],
  options?: {
    k?: number; // Constant to prevent very high ranks from dominating
  }
): RankedDocument[] {
  const { k = 60 } = options || {};
  const documentScores = new Map<string, number>();
  const documentData = new Map<string, RankedDocument>();

  // Calculate RRF score for each document
  for (const rankedList of rankedLists) {
    rankedList.forEach((doc, rank) => {
      const rrfScore = 1 / (k + rank + 1);
      const currentScore = documentScores.get(doc.id) || 0;
      documentScores.set(doc.id, currentScore + rrfScore);

      if (!documentData.has(doc.id)) {
        documentData.set(doc.id, doc);
      }
    });
  }

  // Convert to array and sort by score
  const results: RankedDocument[] = Array.from(documentScores.entries())
    .map(([id, score]) => ({
      ...documentData.get(id)!,
      score,
    }))
    .sort((a, b) => b.score - a.score);

  return results;
}

/**
 * Normalize scores to 0-1 range
 */
export function normalizeScores(documents: RankedDocument[]): RankedDocument[] {
  if (documents.length === 0) return documents;

  const maxScore = Math.max(...documents.map((d) => d.score));
  const minScore = Math.min(...documents.map((d) => d.score));
  const range = maxScore - minScore;

  if (range === 0) {
    return documents.map((doc) => ({ ...doc, score: 1.0 }));
  }

  return documents.map((doc) => ({
    ...doc,
    score: (doc.score - minScore) / range,
  }));
}

/**
 * Apply metadata boosting to scores
 * Boost scores based on document metadata (recency, type, importance)
 */
export function applyMetadataBoost(
  documents: RankedDocument[],
  boostConfig?: {
    recencyBoost?: number; // Boost factor for recent documents (0-1)
    typeBoosts?: Record<string, number>; // Boost factors by document type
    customBoosts?: (doc: RankedDocument) => number; // Custom boost function
  }
): RankedDocument[] {
  const {
    recencyBoost = 0.1,
    typeBoosts = {},
    customBoosts,
  } = boostConfig || {};

  const now = Date.now();
  const oneMonth = 30 * 24 * 60 * 60 * 1000;

  return documents.map((doc) => {
    let boost = 1.0;

    // Recency boost
    if (doc.metadata?.timestamp) {
      const age = now - doc.metadata.timestamp;
      const recencyFactor = Math.max(0, 1 - age / oneMonth);
      boost += recencyFactor * recencyBoost;
    }

    // Type boost
    if (doc.metadata?.type && typeBoosts[doc.metadata.type]) {
      boost *= typeBoosts[doc.metadata.type];
    }

    // Custom boost
    if (customBoosts) {
      boost *= customBoosts(doc);
    }

    return {
      ...doc,
      score: doc.score * boost,
    };
  });
}

/**
 * Tokenize text for keyword matching
 */
export function tokenize(text: string): string[] {
  // Simple tokenization - split on whitespace and punctuation
  return text
    .toLowerCase()
    .replace(/[^\w\s\u0600-\u06FF]/g, ' ') // Keep Arabic characters
    .split(/\s+/)
    .filter((token) => token.length > 1);
}

/**
 * Calculate term frequency for a document
 */
export function calculateTermFrequency(
  text: string
): Map<string, number> {
  const terms = tokenize(text);
  const termFreq = new Map<string, number>();

  for (const term of terms) {
    termFreq.set(term, (termFreq.get(term) || 0) + 1);
  }

  return termFreq;
}

/**
 * Calculate TF-IDF score
 */
export function calculateTfIdf(
  term: string,
  document: string,
  corpus: string[]
): number {
  const terms = tokenize(document);
  const tf = terms.filter((t) => t === term).length / terms.length;

  const docsWithTerm = corpus.filter((doc) =>
    tokenize(doc).includes(term)
  ).length;
  const idf = Math.log(corpus.length / (docsWithTerm + 1));

  return tf * idf;
}

/**
 * Re-rank documents using cross-encoder or advanced models
 * Placeholder for future implementation with more sophisticated models
 */
export async function reRankDocuments(
  query: string,
  documents: RankedDocument[],
  topK?: number
): Promise<RankedDocument[]> {
  // For now, this is a placeholder
  // In production, you might use:
  // - Cross-encoder models for re-ranking
  // - More sophisticated semantic similarity
  // - User behavior signals

  // Simple re-ranking based on query term coverage
  const queryTerms = tokenize(query);

  const reRanked = documents.map((doc) => {
    const docTerms = tokenize(doc.content);
    const coverage = queryTerms.filter((term) => docTerms.includes(term)).length;
    const coverageScore = coverage / queryTerms.length;

    return {
      ...doc,
      score: doc.score * 0.7 + coverageScore * 0.3, // Blend original and coverage scores
    };
  });

  reRanked.sort((a, b) => b.score - a.score);

  return topK ? reRanked.slice(0, topK) : reRanked;
}

/**
 * Highlight query terms in document content
 */
export function highlightMatches(
  content: string,
  queryTerms: string[],
  options?: {
    maxSnippets?: number;
    snippetLength?: number;
    highlightTag?: string;
  }
): string[] {
  const {
    maxSnippets = 3,
    snippetLength = 150,
    highlightTag = '<mark>',
  } = options || {};

  const closeTag = highlightTag.replace('<', '</');
  const snippets: string[] = [];
  const lowerContent = content.toLowerCase();

  for (const term of queryTerms) {
    const lowerTerm = term.toLowerCase();
    let index = lowerContent.indexOf(lowerTerm);

    while (index !== -1 && snippets.length < maxSnippets) {
      const start = Math.max(0, index - snippetLength / 2);
      const end = Math.min(content.length, index + snippetLength / 2);

      let snippet = content.slice(start, end);

      // Highlight the term
      const regex = new RegExp(`(${term})`, 'gi');
      snippet = snippet.replace(regex, `${highlightTag}$1${closeTag}`);

      snippets.push((start > 0 ? '...' : '') + snippet + (end < content.length ? '...' : ''));

      index = lowerContent.indexOf(lowerTerm, index + 1);
    }

    if (snippets.length >= maxSnippets) break;
  }

  return snippets;
}
"}

