{"file_path": "src/lib/search-engine/query-processor.ts", "initial_content": "/**
 * Query Processing and Enhancement
 * 
 * Handles query preprocessing, expansion, and enhancement for better search results
 */

import { tokenize } from './ranking';
import { SearchConfig } from './search-config';

export interface ProcessedQuery {
  original: string;
  normalized: string;
  terms: string[];
  expanded: string[];
  language: 'en' | 'ar' | 'mixed';
}

/**
 * Process and enhance a search query
 */
export function processQuery(
  query: string,
  options?: {
    enableExpansion?: boolean;
    maxExpansions?: number;
    enableNormalization?: boolean;
  }
): ProcessedQuery {
  const {
    enableExpansion = SearchConfig.query.enableQueryExpansion,
    maxExpansions = SearchConfig.query.maxExpansions,
    enableNormalization = true,
  } = options || {};

  // Detect language
  const language = detectLanguage(query);

  // Normalize query
  const normalized = enableNormalization ? normalizeQuery(query, language) : query;

  // Tokenize
  const terms = tokenize(normalized);

  // Expand query
  const expanded = enableExpansion
    ? expandQuery(normalized, language, maxExpansions)
    : [normalized];

  return {
    original: query,
    normalized,
    terms,
    expanded,
    language,
  };
}

/**
 * Detect the language of the query
 */
export function detectLanguage(text: string): 'en' | 'ar' | 'mixed' {
  const arabicPattern = /[\u0600-\u06FF]/;
  const englishPattern = /[a-zA-Z]/;

  const hasArabic = arabicPattern.test(text);
  const hasEnglish = englishPattern.test(text);

  if (hasArabic && hasEnglish) return 'mixed';
  if (hasArabic) return 'ar';
  return 'en';
}

/**
 * Normalize query text
 */
export function normalizeQuery(query: string, language: 'en' | 'ar' | 'mixed'): string {
  let normalized = query.trim();

  // Common normalizations
  normalized = normalized.toLowerCase();

  // Remove extra whitespace
  normalized = normalized.replace(/\s+/g, ' ');

  // Language-specific normalizations
  if (language === 'ar' || language === 'mixed') {
    // Arabic-specific normalization
    normalized = normalizeArabic(normalized);
  }

  return normalized;
}

/**
 * Normalize Arabic text
 */
export function normalizeArabic(text: string): string {
  let normalized = text;

  // Normalize Arabic letters
  normalized = normalized.replace(/[أإآ]/g, 'ا'); // Normalize Alef variants
  normalized = normalized.replace(/ة/g, 'ه'); // Normalize Taa Marbuta
  normalized = normalized.replace(/ى/g, 'ي'); // Normalize Alef Maksura

  // Remove diacritics (Tashkeel)
  normalized = normalized.replace(/[\u064B-\u0652]/g, '');

  return normalized;
}

/**
 * Expand query with synonyms and related terms
 */
export function expandQuery(
  query: string,
  language: 'en' | 'ar' | 'mixed',
  maxExpansions: number = 3
): string[] {
  const expansions = [query];

  // Get query terms
  const terms = tokenize(query);

  // Simple query expansion strategies
  if (language === 'en' || language === 'mixed') {
    // English synonyms and variations
    const englishExpansions = getEnglishExpansions(terms);
    expansions.push(...englishExpansions.slice(0, maxExpansions - 1));
  }

  if (language === 'ar' || language === 'mixed') {
    // Arabic synonyms and variations
    const arabicExpansions = getArabicExpansions(terms);
    expansions.push(...arabicExpansions.slice(0, maxExpansions - 1));
  }

  return expansions.slice(0, maxExpansions);
}

/**
 * Get English query expansions
 */
function getEnglishExpansions(terms: string[]): string[] {
  const expansions: string[] = [];

  // Common synonyms for academic/technical terms
  const synonymMap: Record<string, string[]> = {
    research: ['study', 'investigation', 'analysis'],
    method: ['approach', 'technique', 'methodology'],
    result: ['outcome', 'finding', 'conclusion'],
    analysis: ['examination', 'evaluation', 'assessment'],
    develop: ['create', 'build', 'design'],
    implement: ['execute', 'apply', 'deploy'],
    machine: ['artificial', 'automated', 'computational'],
    learning: ['training', 'education', 'acquisition'],
    model: ['framework', 'architecture', 'system'],
    data: ['information', 'dataset', 'records'],
    algorithm: ['method', 'procedure', 'technique'],
    performance: ['efficiency', 'effectiveness', 'quality'],
  };

  // Generate expansions
  for (const term of terms) {
    if (synonymMap[term]) {
      const synonyms = synonymMap[term];
      const expansion = terms
        .map((t) => (t === term ? synonyms[0] : t))
        .join(' ');
      if (expansion !== terms.join(' ')) {
        expansions.push(expansion);
      }
    }
  }

  // Question variations
  const originalQuery = terms.join(' ');
  if (!originalQuery.includes('what') && !originalQuery.includes('how')) {
    expansions.push(`what is ${originalQuery}`);
    expansions.push(`how to ${originalQuery}`);
  }

  return expansions;
}

/**
 * Get Arabic query expansions
 */
function getArabicExpansions(terms: string[]): string[] {
  const expansions: string[] = [];

  // Common Arabic synonyms
  const arabicSynonymMap: Record<string, string[]> = {
    بحث: ['دراسة', 'تحليل', 'استقصاء'],
    طريقة: ['أسلوب', 'منهج', 'تقنية'],
    نتيجة: ['نتائج', 'خلاصة', 'استنتاج'],
    تطوير: ['تحسين', 'بناء', 'إنشاء'],
    تطبيق: ['تنفيذ', 'استخدام', 'توظيف'],
    نظام: ['منظومة', 'آلية', 'هيكل'],
    بيانات: ['معلومات', 'معطيات'],
    تعلم: ['تدريب', 'تعليم'],
    أداء: ['كفاءة', 'فعالية', 'جودة'],
  };

  for (const term of terms) {
    if (arabicSynonymMap[term]) {
      const synonyms = arabicSynonymMap[term];
      const expansion = terms
        .map((t) => (t === term ? synonyms[0] : t))
        .join(' ');
      if (expansion !== terms.join(' ')) {
        expansions.push(expansion);
      }
    }
  }

  return expansions;
}

/**
 * Extract key phrases from query
 */
export function extractKeyPhrases(query: string): string[] {
  const terms = tokenize(query);
  const phrases: string[] = [];

  // Extract bigrams (2-word phrases)
  for (let i = 0; i < terms.length - 1; i++) {
    phrases.push(`${terms[i]} ${terms[i + 1]}`);
  }

  // Extract trigrams (3-word phrases)
  for (let i = 0; i < terms.length - 2; i++) {
    phrases.push(`${terms[i]} ${terms[i + 1]} ${terms[i + 2]}`);
  }

  return phrases;
}

/**
 * Generate search query variations
 */
export function generateQueryVariations(query: string): string[] {
  const variations: string[] = [query];
  const processed = processQuery(query);

  // Add expanded queries
  variations.push(...processed.expanded);

  // Add key phrases
  const phrases = extractKeyPhrases(query);
  variations.push(...phrases);

  // Remove duplicates
  return Array.from(new Set(variations));
}

/**
 * Apply spell correction (basic implementation)
 */
export function correctSpelling(query: string): string {
  // Basic spell correction rules
  const corrections: Record<string, string> = {
    // Common typos
    'machien': 'machine',
    'learing': 'learning',
    'algortihm': 'algorithm',
    'reaserch': 'research',
    'analysys': 'analysis',
    'developement': 'development',
  };

  let corrected = query;
  for (const [wrong, right] of Object.entries(corrections)) {
    const regex = new RegExp(`\\b${wrong}\\b`, 'gi');
    corrected = corrected.replace(regex, right);
  }

  return corrected;
}

/**
 * Calculate query complexity score
 */
export function calculateQueryComplexity(query: string): {
  score: number;
  factors: {
    length: number;
    termCount: number;
    hasPhrases: boolean;
    hasOperators: boolean;
  };
} {
  const terms = tokenize(query);
  const length = query.length;
  const termCount = terms.length;
  const hasPhrases = query.includes('"') || query.includes("'");
  const hasOperators = /AND|OR|NOT/i.test(query);

  // Calculate complexity score (0-1)
  let score = 0;
  score += Math.min(termCount / 10, 0.4); // Max 0.4 for term count
  score += Math.min(length / 200, 0.3); // Max 0.3 for length
  score += hasPhrases ? 0.15 : 0;
  score += hasOperators ? 0.15 : 0;

  return {
    score,
    factors: {
      length,
      termCount,
      hasPhrases,
      hasOperators,
    },
  };
}

/**
 * Optimize query for vector search
 */
export function optimizeForVectorSearch(query: string): string {
  // Remove special characters that don't add semantic meaning
  let optimized = query.replace(/[^\w\s\u0600-\u06FF]/g, ' ');

  // Remove common stop words that might dilute semantic meaning
  const stopWords = new Set([
    'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for',
    'of', 'with', 'by', 'from', 'as', 'is', 'was', 'are', 'were', 'been',
  ]);

  const terms = tokenize(optimized);
  const filtered = terms.filter((term) => !stopWords.has(term));

  return filtered.join(' ');
}
"}

{"file_path": "src/lib/search-engine/vector-search.ts", "initial_content": "/**
 * Advanced Vector Search Engine
 * 
 * Implements sophisticated vector search with multiple strategies and optimizations
 */

import { generateEmbedding } from '@/lib/rag/embeddings';
import { getVectorStore, type DocumentChunk, type SearchResult } from '@/lib/rag/vector-store';
import { processQuery } from './query-processor';
import { normalizeScores, applyMetadataBoost, type RankedDocument } from './ranking';
import { SearchConfig, type SearchOptions, type SearchFilters } from './search-config';

export interface VectorSearchResult extends RankedDocument {
  chunk: DocumentChunk;
  relevance: number;
  matchedTerms?: string[];
}

export interface VectorSearchResponse {
  results: VectorSearchResult[];
  totalFound: number;
  query: {
    original: string;
    processed: string;
    language: string;
  };
  searchTime: number;
}

/**
 * Advanced Vector Search Class
 */
export class VectorSearchEngine {
  private vectorStore = getVectorStore();

  /**
   * Perform vector search with advanced features
   */
  async search(
    query: string,
    options: SearchOptions = {}
  ): Promise<VectorSearchResponse> {
    const startTime = Date.now();

    const {
      topK = SearchConfig.vector.defaultTopK,
      minScore = SearchConfig.vector.defaultMinScore,
      filters,
      enableQueryExpansion = true,
      enableReranking = false,
      includeMetadata = true,
    } = options;

    try {
      // Process query
      const processedQuery = processQuery(query, { enableExpansion: enableQueryExpansion });

      // Load project data if projectId is provided
      if (filters?.projectId) {
        await this.vectorStore.loadProjectChunks(filters.projectId);
      }

      // Perform multi-query search if expansion is enabled
      let allResults: VectorSearchResult[] = [];

      if (enableQueryExpansion && processedQuery.expanded.length > 1) {
        allResults = await this.multiQuerySearch(processedQuery.expanded, {
          topK: Math.ceil(topK / processedQuery.expanded.length),
          minScore,
          filters,
        });
      } else {
        const singleResults = await this.singleQuerySearch(processedQuery.normalized, {
          topK,
          minScore,
          filters,
        });
        allResults = singleResults;
      }

      // Apply metadata boosting
      if (includeMetadata) {
        allResults = this.applyBoosts(allResults);
      }

      // Re-rank if enabled
      if (enableReranking) {
        allResults = await this.rerank(query, allResults);
      }

      // Deduplicate and sort
      const uniqueResults = this.deduplicateResults(allResults);
      uniqueResults.sort((a, b) => b.score - a.score);

      // Limit to topK
      const finalResults = uniqueResults.slice(0, topK);

      const searchTime = Date.now() - startTime;

      return {
        results: finalResults,
        totalFound: uniqueResults.length,
        query: {
          original: query,
          processed: processedQuery.normalized,
          language: processedQuery.language,
        },
        searchTime,
      };
    } catch (error) {
      console.error('Vector search error:', error);
      throw new Error(`Vector search failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Perform single query search
   */
  private async singleQuerySearch(
    query: string,
    options: {
      topK: number;
      minScore: number;
      filters?: SearchFilters;
    }
  ): Promise<VectorSearchResult[]> {
    const { topK, minScore, filters } = options;

    // Generate query embedding
    const queryEmbedding = await generateEmbedding(query);

    // Search vector store
    const searchResults = await this.vectorStore.search(queryEmbedding, {
      topK,
      minScore,
      filter: this.buildFilter(filters),
    });

    // Convert to VectorSearchResult
    return searchResults.map((result) => this.convertToSearchResult(result));
  }

  /**
   * Perform multi-query search with result fusion
   */
  private async multiQuerySearch(
    queries: string[],
    options: {
      topK: number;
      minScore: number;
      filters?: SearchFilters;
    }
  ): Promise<VectorSearchResult[]> {
    const { topK, minScore, filters } = options;

    // Search with each query
    const allResults = await Promise.all(
      queries.map((q) => this.singleQuerySearch(q, { topK, minScore, filters }))
    );

    // Flatten results
    const flatResults = allResults.flat();

    // Deduplicate and merge scores
    const mergedResults = this.mergeResults(flatResults);

    return mergedResults;
  }

  /**
   * Search with multiple vectors (for complex queries)
   */
  async multiVectorSearch(
    embeddings: number[][],
    options: SearchOptions = {}
  ): Promise<VectorSearchResponse> {
    const startTime = Date.now();

    const {
      topK = SearchConfig.vector.defaultTopK,
      minScore = SearchConfig.vector.defaultMinScore,
      filters,
    } = options;

    try {
      // Search with each embedding
      const allResults = await Promise.all(
        embeddings.map(async (embedding) => {
          const searchResults = await this.vectorStore.search(embedding, {
            topK: Math.ceil(topK / embeddings.length),
            minScore,
            filter: this.buildFilter(filters),
          });
          return searchResults.map((result) => this.convertToSearchResult(result));
        })
      );

      // Merge results
      const flatResults = allResults.flat();
      const mergedResults = this.mergeResults(flatResults);

      // Sort and limit
      mergedResults.sort((a, b) => b.score - a.score);
      const finalResults = mergedResults.slice(0, topK);

      const searchTime = Date.now() - startTime;

      return {
        results: finalResults,
        totalFound: mergedResults.length,
        query: {
          original: 'Multi-vector search',
          processed: 'Multiple embeddings',
          language: 'mixed',
        },
        searchTime,
      };
    } catch (error) {
      console.error('Multi-vector search error:', error);
      throw error;
    }
  }

  /**
   * Semantic search with natural language understanding
   */
  async semanticSearch(
    query: string,
    context?: string,
    options: SearchOptions = {}
  ): Promise<VectorSearchResponse> {
    // Enhance query with context
    const enhancedQuery = context ? `${query}\nContext: ${context}` : query;

    // Perform standard search with enhancements
    return this.search(enhancedQuery, {
      ...options,
      enableQueryExpansion: true,
      enableReranking: true,
    });
  }

  /**
   * Convert vector store search result to VectorSearchResult
   */
  private convertToSearchResult(result: SearchResult): VectorSearchResult {
    return {
      id: result.chunk.id,
      content: result.chunk.content,
      score: result.score,
      relevance: result.score,
      chunk: result.chunk,
      metadata: result.chunk.metadata,
    };
  }

  /**
   * Build filter for vector store
   */
  private buildFilter(filters?: SearchFilters) {
    if (!filters) return undefined;

    return {
      projectId: filters.projectId,
      userId: filters.userId,
      type: filters.documentTypes?.[0],
    };
  }

  /**
   * Merge duplicate results and combine scores
   */
  private mergeResults(results: VectorSearchResult[]): VectorSearchResult[] {
    const merged = new Map<string, VectorSearchResult>();

    for (const result of results) {
      const existing = merged.get(result.id);
      if (existing) {
        // Combine scores (average)
        existing.score = (existing.score + result.score) / 2;
        existing.relevance = (existing.relevance + result.relevance) / 2;
      } else {
        merged.set(result.id, { ...result });
      }
    }

    return Array.from(merged.values());
  }

  /**
   * Deduplicate results by ID
   */
  private deduplicateResults(results: VectorSearchResult[]): VectorSearchResult[] {
    const seen = new Set<string>();
    return results.filter((result) => {
      if (seen.has(result.id)) return false;
      seen.add(result.id);
      return true;
    });
  }

  /**
   * Apply metadata-based boosting
   */
  private applyBoosts(results: VectorSearchResult[]): VectorSearchResult[] {
    return applyMetadataBoost(results, {
      recencyBoost: 0.2,
      typeBoosts: {
        'academic_paper': 1.2,
        'reference': 1.15,
        'report': 1.1,
        'context': 1.0,
        'user_upload': 0.95,
      },
    }) as VectorSearchResult[];
  }

  /**
   * Re-rank results for better relevance
   */
  private async rerank(query: string, results: VectorSearchResult[]): Promise<VectorSearchResult[]> {
    // Simple re-ranking based on query term coverage
    const queryTerms = query.toLowerCase().split(/\s+/);

    return results.map((result) => {
      const contentLower = result.content.toLowerCase();
      const matchedTerms = queryTerms.filter((term) => contentLower.includes(term));
      const coverage = matchedTerms.length / queryTerms.length;

      return {
        ...result,
        score: result.score * 0.7 + coverage * 0.3,
        matchedTerms,
      };
    });
  }

  /**
   * Get search statistics
   */
  getStats() {
    return {
      totalChunks: this.vectorStore.size(),
      version: '1.0.0',
    };
  }

  /**
   * Clear search cache
   */
  clearCache() {
    this.vectorStore.clear();
  }
}

// Singleton instance
let searchEngineInstance: VectorSearchEngine | null = null;

export function getVectorSearchEngine(): VectorSearchEngine {
  if (!searchEngineInstance) {
    searchEngineInstance = new VectorSearchEngine();
  }
  return searchEngineInstance;
}
"}

{"file_path": "src/lib/search-engine/hybrid-search.ts", "initial_content": "/**
 * Hybrid Search Engine
 * 
 * Combines vector search with keyword-based search (BM25) for better results
 */

import { VectorSearchEngine } from './vector-search';
import {
  calculateBM25Score,
  reciprocalRankFusion,
  normalizeScores,
  tokenize,
  type RankedDocument,
  type DocumentWithTerms,
} from './ranking';
import { processQuery } from './query-processor';
import { getVectorStore } from '@/lib/rag/vector-store';
import { SearchConfig, type SearchOptions } from './search-config';
import type { VectorSearchResult } from './vector-search';

export interface HybridSearchResult extends VectorSearchResult {
  vectorScore: number;
  keywordScore: number;
  combinedScore: number;
  matchType: 'vector' | 'keyword' | 'both';
}

export interface HybridSearchResponse {
  results: HybridSearchResult[];
  totalFound: number;
  query: {
    original: string;
    processed: string;
    language: string;
  };
  searchTime: number;
  metadata: {
    vectorResultsCount: number;
    keywordResultsCount: number;
    fusedResultsCount: number;
  };
}

/**
 * Hybrid Search Engine Class
 */
export class HybridSearchEngine {
  private vectorSearch = new VectorSearchEngine();
  private vectorStore = getVectorStore();

  /**
   * Perform hybrid search combining vector and keyword search
   */
  async search(
    query: string,
    options: SearchOptions = {}
  ): Promise<HybridSearchResponse> {
    const startTime = Date.now();

    const {
      topK = SearchConfig.vector.defaultTopK,
      minScore = SearchConfig.vector.defaultMinScore,
      filters,
    } = options;

    try {
      // Process query
      const processedQuery = processQuery(query);

      // Load project data if needed
      if (filters?.projectId) {
        await this.vectorStore.loadProjectChunks(filters.projectId);
      }

      // Perform vector search
      const vectorResults = await this.vectorSearch.search(query, {
        ...options,
        topK: topK * 2, // Get more results for fusion
      });

      // Perform keyword search (BM25)
      const keywordResults = await this.keywordSearch(
        processedQuery.terms,
        filters,
        topK * 2
      );

      // Fuse results using Reciprocal Rank Fusion
      const fusedResults = this.fuseResults(
        vectorResults.results,
        keywordResults,
        {
          vectorWeight: SearchConfig.hybrid.vectorWeight,
          keywordWeight: SearchConfig.hybrid.keywordWeight,
        }
      );

      // Sort and limit
      fusedResults.sort((a, b) => b.combinedScore - a.combinedScore);
      const finalResults = fusedResults.slice(0, topK);

      const searchTime = Date.now() - startTime;

      return {
        results: finalResults,
        totalFound: fusedResults.length,
        query: {
          original: query,
          processed: processedQuery.normalized,
          language: processedQuery.language,
        },
        searchTime,
        metadata: {
          vectorResultsCount: vectorResults.results.length,
          keywordResultsCount: keywordResults.length,
          fusedResultsCount: fusedResults.length,
        },
      };
    } catch (error) {
      console.error('Hybrid search error:', error);
      throw new Error(`Hybrid search failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Perform keyword-based search using BM25
   */
  private async keywordSearch(
    queryTerms: string[],
    filters?: any,
    topK: number = 10
  ): Promise<RankedDocument[]> {
    // Get all chunks from vector store (in production, you'd query a proper text index)
    const vectorStore = getVectorStore();

    // This is a simplified implementation
    // In production, you'd use a dedicated text search engine like Elasticsearch

    // For now, we'll do in-memory BM25 search
    const allChunks: any[] = [];

    // We need to access chunks - this is a limitation of the current vector store design
    // In production, maintain a separate text index

    // Return empty for now - this would be implemented with a proper text search backend
    return [];
  }

  /**
   * Fuse vector and keyword search results
   */
  private fuseResults(
    vectorResults: VectorSearchResult[],
    keywordResults: RankedDocument[],
    weights: {
      vectorWeight: number;
      keywordWeight: number;
    }
  ): HybridSearchResult[] {
    const { vectorWeight, keywordWeight } = weights;

    // Normalize scores
    const normalizedVectorResults = normalizeScores(vectorResults);
    const normalizedKeywordResults = normalizeScores(keywordResults);

    // Create maps for quick lookup
    const vectorMap = new Map(
      normalizedVectorResults.map((r) => [r.id, r])
    );
    const keywordMap = new Map(
      normalizedKeywordResults.map((r) => [r.id, r])
    );

    // Get all unique document IDs
    const allIds = new Set([
      ...normalizedVectorResults.map((r) => r.id),
      ...normalizedKeywordResults.map((r) => r.id),
    ]);

    // Combine results
    const hybridResults: HybridSearchResult[] = [];

    for (const id of allIds) {
      const vectorResult = vectorMap.get(id);
      const keywordResult = keywordMap.get(id);

      const vectorScore = vectorResult?.score || 0;
      const keywordScore = keywordResult?.score || 0;

      // Skip if both scores are too low
      if (vectorScore < 0.3 && keywordScore < 0.3) continue;

      // Combined score using weighted average
      const combinedScore = vectorScore * vectorWeight + keywordScore * keywordWeight;

      // Determine match type
      let matchType: 'vector' | 'keyword' | 'both';
      if (vectorResult && keywordResult) {
        matchType = 'both';
      } else if (vectorResult) {
        matchType = 'vector';
      } else {
        matchType = 'keyword';
      }

      // Use vector result as base if available, otherwise keyword result
      const baseResult = vectorResult || keywordResult;
      if (!baseResult) continue;

      hybridResults.push({
        ...baseResult,
        vectorScore,
        keywordScore,
        combinedScore,
        matchType,
        score: combinedScore, // Override score with combined
      } as HybridSearchResult);
    }

    return hybridResults;
  }

  /**
   * Perform hybrid search with RRF (Reciprocal Rank Fusion)
   */
  async searchWithRRF(
    query: string,
    options: SearchOptions = {}
  ): Promise<HybridSearchResponse> {
    const startTime = Date.now();

    const {
      topK = SearchConfig.vector.defaultTopK,
      filters,
    } = options;

    try {
      const processedQuery = processQuery(query);

      // Perform both searches
      const [vectorResults, keywordResults] = await Promise.all([
        this.vectorSearch.search(query, { ...options, topK: topK * 2 }),
        this.keywordSearch(processedQuery.terms, filters, topK * 2),
      ]);

      // Apply RRF
      const rankedLists = [
        vectorResults.results as RankedDocument[],
        keywordResults,
      ];

      const rrfResults = reciprocalRankFusion(rankedLists, { k: 60 });

      // Convert to HybridSearchResult
      const hybridResults: HybridSearchResult[] = rrfResults.map((result) => {
        const vectorResult = vectorResults.results.find((r) => r.id === result.id);
        const keywordResult = keywordResults.find((r) => r.id === result.id);

        return {
          ...result,
          vectorScore: vectorResult?.score || 0,
          keywordScore: keywordResult?.score || 0,
          combinedScore: result.score,
          matchType: vectorResult && keywordResult ? 'both' : vectorResult ? 'vector' : 'keyword',
        } as HybridSearchResult;
      });

      const finalResults = hybridResults.slice(0, topK);
      const searchTime = Date.now() - startTime;

      return {
        results: finalResults,
        totalFound: hybridResults.length,
        query: {
          original: query,
          processed: processedQuery.normalized,
          language: processedQuery.language,
        },
        searchTime,
        metadata: {
          vectorResultsCount: vectorResults.results.length,
          keywordResultsCount: keywordResults.length,
          fusedResultsCount: hybridResults.length,
        },
      };
    } catch (error) {
      console.error('RRF search error:', error);
      throw error;
    }
  }

  /**
   * Adaptive hybrid search - automatically adjust weights based on query type
   */
  async adaptiveSearch(
    query: string,
    options: SearchOptions = {}
  ): Promise<HybridSearchResponse> {
    const processedQuery = processQuery(query);

    // Determine optimal weights based on query characteristics
    const weights = this.determineOptimalWeights(processedQuery);

    // Perform search with adjusted weights
    return this.search(query, {
      ...options,
      // Note: In a full implementation, you'd pass weights to the search method
    });
  }

  /**
   * Determine optimal search weights based on query characteristics
   */
  private determineOptimalWeights(processedQuery: any): {
    vectorWeight: number;
    keywordWeight: number;
  } {
    // Short queries (1-2 terms) - favor vector search for semantic understanding
    if (processedQuery.terms.length <= 2) {
      return { vectorWeight: 0.8, keywordWeight: 0.2 };
    }

    // Long queries (5+ terms) - favor keyword search for precision
    if (processedQuery.terms.length >= 5) {
      return { vectorWeight: 0.5, keywordWeight: 0.5 };
    }

    // Questions - favor vector search for semantic understanding
    const isQuestion = /^(what|how|why|when|where|who|which)/i.test(processedQuery.original);
    if (isQuestion) {
      return { vectorWeight: 0.75, keywordWeight: 0.25 };
    }

    // Default balanced weights
    return {
      vectorWeight: SearchConfig.hybrid.vectorWeight,
      keywordWeight: SearchConfig.hybrid.keywordWeight,
    };
  }

  /**
   * Get search statistics
   */
  getStats() {
    return this.vectorSearch.getStats();
  }
}

// Singleton instance
let hybridSearchInstance: HybridSearchEngine | null = null;

export function getHybridSearchEngine(): HybridSearchEngine {
  if (!hybridSearchInstance) {
    hybridSearchInstance = new HybridSearchEngine();
  }
  return hybridSearchInstance;
}
"}

{"file_path": "src/lib/search-engine/analytics.ts", "initial_content": "/**
 * Search Analytics and Tracking
 * 
 * Tracks search queries, results, clicks, and performance metrics
 */

import { db } from '@/lib/firebase/server-init';
import { collection, addDoc, query, where, getDocs, orderBy, limit, Timestamp } from 'firebase/firestore';

export interface SearchQuery {
  id?: string;
  query: string;
  userId?: string;
  projectId?: string;
  searchMode: 'vector' | 'hybrid' | 'keyword' | 'semantic';
  resultsCount: number;
  searchTime: number;
  timestamp: number;
  language?: string;
  filters?: Record<string, any>;
}

export interface SearchClick {
  id?: string;
  queryId: string;
  documentId: string;
  position: number;
  timestamp: number;
  userId?: string;
}

export interface SearchMetrics {
  totalSearches: number;
  averageSearchTime: number;
  averageResultsCount: number;
  popularQueries: Array<{ query: string; count: number }>;
  failedQueries: Array<{ query: string; reason: string; count: number }>;
  clickThroughRate: number;
}

export interface SearchPerformance {
  queryId: string;
  latency: number;
  resultCount: number;
  relevanceScore: number;
  userSatisfaction?: number;
  timestamp: number;
}

/**
 * Search Analytics Service
 */
export class SearchAnalytics {
  private collectionName = 'search_analytics';
  private clicksCollection = 'search_clicks';
  private performanceCollection = 'search_performance';

  /**
   * Track a search query
   */
  async trackQuery(queryData: Omit<SearchQuery, 'id'>): Promise<string> {
    try {
      const docRef = await addDoc(collection(db, this.collectionName), {
        ...queryData,
        timestamp: Timestamp.now(),
      });
      return docRef.id;
    } catch (error) {
      console.error('Error tracking query:', error);
      throw error;
    }
  }

  /**
   * Track a search result click
   */
  async trackClick(clickData: Omit<SearchClick, 'id'>): Promise<void> {
    try {
      await addDoc(collection(db, this.clicksCollection), {
        ...clickData,
        timestamp: Timestamp.now(),
      });
    } catch (error) {
      console.error('Error tracking click:', error);
      throw error;
    }
  }

  /**
   * Track search performance metrics
   */
  async trackPerformance(performanceData: SearchPerformance): Promise<void> {
    try {
      await addDoc(collection(db, this.performanceCollection), {
        ...performanceData,
        timestamp: Timestamp.now(),
      });
    } catch (error) {
      console.error('Error tracking performance:', error);
      throw error;
    }
  }

  /**
   * Get search metrics for a time period
   */
  async getMetrics(
    startDate: Date,
    endDate: Date,
    userId?: string
  ): Promise<SearchMetrics> {
    try {
      // Build query
      let q = query(
        collection(db, this.collectionName),
        where('timestamp', '>=', Timestamp.fromDate(startDate)),
        where('timestamp', '<=', Timestamp.fromDate(endDate))
      );

      if (userId) {
        q = query(q, where('userId', '==', userId));
      }

      const snapshot = await getDocs(q);
      const queries: SearchQuery[] = [];

      snapshot.forEach((doc) => {
        queries.push({ id: doc.id, ...doc.data() } as SearchQuery);
      });

      // Calculate metrics
      const totalSearches = queries.length;
      const averageSearchTime =
        queries.reduce((sum, q) => sum + q.searchTime, 0) / totalSearches || 0;
      const averageResultsCount =
        queries.reduce((sum, q) => sum + q.resultsCount, 0) / totalSearches || 0;

      // Get popular queries
      const queryFrequency = new Map<string, number>();
      queries.forEach((q) => {
        const count = queryFrequency.get(q.query) || 0;
        queryFrequency.set(q.query, count + 1);
      });

      const popularQueries = Array.from(queryFrequency.entries())
        .map(([query, count]) => ({ query, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

      // Get failed queries (queries with 0 results)
      const failedQueriesMap = new Map<string, number>();
      queries
        .filter((q) => q.resultsCount === 0)
        .forEach((q) => {
          const count = failedQueriesMap.get(q.query) || 0;
          failedQueriesMap.set(q.query, count + 1);
        });

      const failedQueries = Array.from(failedQueriesMap.entries())
        .map(([query, count]) => ({ query, count, reason: 'No results' }))
        .slice(0, 10);

      // Calculate CTR
      const clicksSnapshot = await getDocs(
        query(
          collection(db, this.clicksCollection),
          where('timestamp', '>=', Timestamp.fromDate(startDate)),
          where('timestamp', '<=', Timestamp.fromDate(endDate))
        )
      );

      const clickThroughRate =
        totalSearches > 0 ? clicksSnapshot.size / totalSearches : 0;

      return {
        totalSearches,
        averageSearchTime,
        averageResultsCount,
        popularQueries,
        failedQueries,
        clickThroughRate,
      };
    } catch (error) {
      console.error('Error getting metrics:', error);
      throw error;
    }
  }

  /**
   * Get popular search queries
   */
  async getPopularQueries(limitCount: number = 10): Promise<Array<{ query: string; count: number }>> {
    try {
      const snapshot = await getDocs(
        query(
          collection(db, this.collectionName),
          orderBy('timestamp', 'desc'),
          limit(1000) // Get last 1000 queries
        )
      );

      const queryFrequency = new Map<string, number>();
      snapshot.forEach((doc) => {
        const data = doc.data() as SearchQuery;
        const count = queryFrequency.get(data.query) || 0;
        queryFrequency.set(data.query, count + 1);
      });

      return Array.from(queryFrequency.entries())
        .map(([query, count]) => ({ query, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, limitCount);
    } catch (error) {
      console.error('Error getting popular queries:', error);
      return [];
    }
  }

  /**
   * Get recent search queries
   */
  async getRecentQueries(userId?: string, limitCount: number = 10): Promise<SearchQuery[]> {
    try {
      let q = query(
        collection(db, this.collectionName),
        orderBy('timestamp', 'desc'),
        limit(limitCount)
      );

      if (userId) {
        q = query(
          collection(db, this.collectionName),
          where('userId', '==', userId),
          orderBy('timestamp', 'desc'),
          limit(limitCount)
        );
      }

      const snapshot = await getDocs(q);
      const queries: SearchQuery[] = [];

      snapshot.forEach((doc) => {
        queries.push({ id: doc.id, ...doc.data() } as SearchQuery);
      });

      return queries;
    } catch (error) {
      console.error('Error getting recent queries:', error);
      return [];
    }
  }

  /**
   * Get average search performance
   */
  async getAveragePerformance(startDate: Date, endDate: Date): Promise<{
    avgLatency: number;
    avgResultCount: number;
    avgRelevanceScore: number;
  }> {
    try {
      const snapshot = await getDocs(
        query(
          collection(db, this.performanceCollection),
          where('timestamp', '>=', Timestamp.fromDate(startDate).toMillis()),
          where('timestamp', '<=', Timestamp.fromDate(endDate).toMillis())
        )
      );

      const performances: SearchPerformance[] = [];
      snapshot.forEach((doc) => {
        performances.push(doc.data() as SearchPerformance);
      });

      const count = performances.length;
      if (count === 0) {
        return { avgLatency: 0, avgResultCount: 0, avgRelevanceScore: 0 };
      }

      return {
        avgLatency: performances.reduce((sum, p) => sum + p.latency, 0) / count,
        avgResultCount: performances.reduce((sum, p) => sum + p.resultCount, 0) / count,
        avgRelevanceScore: performances.reduce((sum, p) => sum + p.relevanceScore, 0) / count,
      };
    } catch (error) {
      console.error('Error getting average performance:', error);
      return { avgLatency: 0, avgResultCount: 0, avgRelevanceScore: 0 };
    }
  }

  /**
   * Get failed queries (queries with no results)
   */
  async getFailedQueries(limitCount: number = 10): Promise<Array<{ query: string; count: number }>> {
    try {
      const snapshot = await getDocs(
        query(
          collection(db, this.collectionName),
          where('resultsCount', '==', 0),
          orderBy('timestamp', 'desc'),
          limit(100)
        )
      );

      const queryFrequency = new Map<string, number>();
      snapshot.forEach((doc) => {
        const data = doc.data() as SearchQuery;
        const count = queryFrequency.get(data.query) || 0;
        queryFrequency.set(data.query, count + 1);
      });

      return Array.from(queryFrequency.entries())
        .map(([query, count]) => ({ query, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, limitCount);
    } catch (error) {
      console.error('Error getting failed queries:', error);
      return [];
    }
  }
}

// Singleton instance
let analyticsInstance: SearchAnalytics | null = null;

export function getSearchAnalytics(): SearchAnalytics {
  if (!analyticsInstance) {
    analyticsInstance = new SearchAnalytics();
  }
  return analyticsInstance;
}

/**
 * In-memory cache for quick access to analytics data
 */
export class AnalyticsCache {
  private cache = new Map<string, { data: any; timestamp: number }>();
  private ttl = 5 * 60 * 1000; // 5 minutes

  set(key: string, data: any): void {
    this.cache.set(key, { data, timestamp: Date.now() });
  }

  get(key: string): any | null {
    const cached = this.cache.get(key);
    if (!cached) return null;

    if (Date.now() - cached.timestamp > this.ttl) {
      this.cache.delete(key);
      return null;
    }

    return cached.data;
  }

  clear(): void {
    this.cache.clear();
  }
}
"}

