{"file_path": "src/services/search-service.ts", "initial_content": "/**
 * Search Service
 * 
 * High-level service layer for search operations
 */

import {
  getVectorSearchEngine,
  getHybridSearchEngine,
  getSearchAnalytics,
  SearchMode,
  type SearchOptions,
  type VectorSearchResponse,
  type HybridSearchResponse,
} from '@/lib/search-engine';

export class SearchService {
  /**
   * Universal search method that routes to appropriate search engine
   */
  static async search(
    query: string,
    options: SearchOptions & {
      userId?: string;
      trackAnalytics?: boolean;
    } = {}
  ): Promise<VectorSearchResponse | HybridSearchResponse> {
    const {
      mode = SearchMode.VECTOR,
      userId,
      trackAnalytics = true,
      ...searchOptions
    } = options;

    const startTime = Date.now();

    try {
      let results: VectorSearchResponse | HybridSearchResponse;

      // Route to appropriate search engine
      switch (mode) {
        case SearchMode.VECTOR:
        case SearchMode.SEMANTIC:
          const vectorEngine = getVectorSearchEngine();
          results = await vectorEngine.search(query, searchOptions);
          break;

        case SearchMode.HYBRID:
          const hybridEngine = getHybridSearchEngine();
          results = await hybridEngine.search(query, searchOptions);
          break;

        case SearchMode.KEYWORD:
          // Fall back to hybrid with keyword-only mode
          const keywordEngine = getHybridSearchEngine();
          results = await keywordEngine.search(query, {
            ...searchOptions,
          });
          break;

        default:
          throw new Error(`Unsupported search mode: ${mode}`);
      }

      // Track analytics
      if (trackAnalytics) {
        await this.trackSearch(query, results, mode, userId);
      }

      return results;
    } catch (error) {
      console.error('Search service error:', error);
      throw new Error(
        `Search failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  /**
   * Vector search
   */
  static async vectorSearch(
    query: string,
    options: SearchOptions = {}
  ): Promise<VectorSearchResponse> {
    const engine = getVectorSearchEngine();
    return engine.search(query, options);
  }

  /**
   * Hybrid search
   */
  static async hybridSearch(
    query: string,
    options: SearchOptions = {}
  ): Promise<HybridSearchResponse> {
    const engine = getHybridSearchEngine();
    return engine.search(query, options);
  }

  /**
   * Semantic search with context
   */
  static async semanticSearch(
    query: string,
    context?: string,
    options: SearchOptions = {}
  ): Promise<VectorSearchResponse> {
    const engine = getVectorSearchEngine();
    return engine.semanticSearch(query, context, options);
  }

  /**
   * Multi-query search
   */
  static async multiQuerySearch(
    queries: string[],
    options: SearchOptions = {}
  ): Promise<VectorSearchResponse[]> {
    const engine = getVectorSearchEngine();
    return Promise.all(queries.map((q) => engine.search(q, options)));
  }

  /**
   * Track search in analytics
   */
  private static async trackSearch(
    query: string,
    results: VectorSearchResponse | HybridSearchResponse,
    mode: SearchMode,
    userId?: string
  ): Promise<void> {
    try {
      const analytics = getSearchAnalytics();
      await analytics.trackQuery({
        query: results.query.original,
        userId,
        searchMode: mode,
        resultsCount: results.totalFound,
        searchTime: results.searchTime,
        language: results.query.language,
        timestamp: Date.now(),
      });
    } catch (error) {
      console.error('Failed to track search analytics:', error);
      // Don't throw - analytics failure shouldn't break search
    }
  }

  /**
   * Track result click
   */
  static async trackClick(
    queryId: string,
    documentId: string,
    position: number,
    userId?: string
  ): Promise<void> {
    try {
      const analytics = getSearchAnalytics();
      await analytics.trackClick({
        queryId,
        documentId,
        position,
        userId,
        timestamp: Date.now(),
      });
    } catch (error) {
      console.error('Failed to track click:', error);
    }
  }

  /**
   * Get search suggestions
   */
  static async getSuggestions(
    partialQuery: string,
    limit: number = 5
  ): Promise<string[]> {
    try {
      const analytics = getSearchAnalytics();
      const popularQueries = await analytics.getPopularQueries(50);

      // Filter queries that start with or contain the partial query
      const suggestions = popularQueries
        .filter((q) =>
          q.query.toLowerCase().includes(partialQuery.toLowerCase())
        )
        .map((q) => q.query)
        .slice(0, limit);

      return suggestions;
    } catch (error) {
      console.error('Failed to get suggestions:', error);
      return [];
    }
  }

  /**
   * Get search analytics
   */
  static async getAnalytics(
    startDate: Date,
    endDate: Date,
    userId?: string
  ) {
    const analytics = getSearchAnalytics();
    return analytics.getMetrics(startDate, endDate, userId);
  }

  /**
   * Get popular queries
   */
  static async getPopularQueries(limit: number = 10) {
    const analytics = getSearchAnalytics();
    return analytics.getPopularQueries(limit);
  }

  /**
   * Get recent queries for a user
   */
  static async getRecentQueries(userId: string, limit: number = 10) {
    const analytics = getSearchAnalytics();
    return analytics.getRecentQueries(userId, limit);
  }

  /**
   * Get failed queries
   */
  static async getFailedQueries(limit: number = 10) {
    const analytics = getSearchAnalytics();
    return analytics.getFailedQueries(limit);
  }
}

export default SearchService;
"}

{"file_path": "src/app/api/search/vector/route.ts", "initial_content": "/**
 * API Route: Vector Search
 * 
 * POST /api/search/vector
 * 
 * Performs vector-based semantic search
 */

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import SearchService from '@/services/search-service';
import { SearchMode } from '@/lib/search-engine';

const VectorSearchSchema = z.object({
  query: z.string().min(1, 'Query is required'),
  userId: z.string().optional(),
  projectId: z.string().optional(),
  topK: z.number().min(1).max(50).default(10),
  minScore: z.number().min(0).max(1).default(0.5),
  enableQueryExpansion: z.boolean().default(true),
  enableReranking: z.boolean().default(false),
  documentTypes: z.array(z.string()).optional(),
  trackAnalytics: z.boolean().default(true),
});

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    // Validate input
    const validation = VectorSearchSchema.safeParse(body);
    if (!validation.success) {
      return NextResponse.json(
        { error: 'Invalid input', details: validation.error.errors },
        { status: 400 }
      );
    }

    const {
      query,
      userId,
      projectId,
      topK,
      minScore,
      enableQueryExpansion,
      enableReranking,
      documentTypes,
      trackAnalytics,
    } = validation.data;

    // Perform search
    const results = await SearchService.search(query, {
      mode: SearchMode.VECTOR,
      topK,
      minScore,
      enableQueryExpansion,
      enableReranking,
      filters: {
        projectId,
        userId,
        documentTypes: documentTypes as any,
      },
      userId,
      trackAnalytics,
    });

    return NextResponse.json({
      success: true,
      ...results,
    });
  } catch (error) {
    console.error('Vector search API error:', error);
    return NextResponse.json(
      {
        error: 'Search failed',
        message: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}
"}

